const page = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>RAG Eval Harness · Braylo</title><style>:root{--navy:#0d1520;--cream:#efe9dc;--brass:#b39b70;--ink:#16202e;--line:#253246}\n*{box-sizing:border-box}body{margin:0;background:var(--navy);color:var(--cream);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}\n.wrap{max-width:860px;margin:0 auto;padding:40px 20px 56px}\nheader .tag{color:var(--brass);letter-spacing:.14em;text-transform:uppercase;font-size:12px;font-weight:600}\nh1{font-family:Georgia,serif;font-weight:500;font-size:34px;margin:6px 0 8px}\n.lead{opacity:.82;max-width:640px;margin:0 0 24px}\n.card{background:var(--ink);border:1px solid var(--line);border-radius:12px;padding:18px;margin:14px 0}\n.card h2{font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:var(--brass);margin:0 0 10px;font-weight:600}\ntextarea,input,select{width:100%;font:inherit;color:var(--cream);background:var(--navy);border:1px solid var(--line);border-radius:8px;padding:10px 12px}\ntextarea:focus,input:focus,select:focus{outline:none;border-color:var(--brass)}\nbutton{font:inherit;font-weight:600;background:var(--brass);color:var(--navy);border:0;border-radius:8px;padding:10px 18px;cursor:pointer}\nbutton.ghost{background:transparent;color:var(--cream);border:1px solid var(--line)}button:disabled{opacity:.5;cursor:wait}\n.row{display:flex;gap:10px;align-items:center;margin-top:10px;flex-wrap:wrap}.row>input,.row>select{flex:1}\n.chips{display:flex;flex-wrap:wrap;gap:8px}.chip{font-size:13px;padding:6px 10px;border-radius:999px;border:1px solid var(--line);background:transparent;color:var(--cream);font-weight:400}\n.chip:hover{border-color:var(--brass)}\n.out{white-space:pre-wrap;min-height:48px}.meta{font-size:12px;opacity:.6;margin-top:8px}\n.pill{display:inline-block;font-size:12px;padding:2px 8px;border-radius:999px;background:rgba(179,155,112,.15);color:var(--brass);margin:2px 4px 2px 0}\npre{background:var(--navy);border:1px solid var(--line);border-radius:8px;padding:12px;overflow:auto;font-size:13px;max-height:360px;margin:0}\nfooter{margin-top:28px;font-size:13px;opacity:.65}a{color:var(--brass)}\ntable{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:6px 8px;border-bottom:1px solid var(--line)}th{color:var(--brass);font-weight:600}\n</style></head>\n<body><div class=\"wrap\"><header><div class=\"tag\">Project 11 · Agentic AI portfolio</div><h1>RAG Eval Harness</h1>\n<p class=\"lead\">Measures a RAG pipeline the way you would before shipping it: retrieval precision@k, recall@k and MRR against labelled relevant chunks, plus answer faithfulness scored by citation overlap (and an optional LLM judge).</p></header>\n<div class=\"card\"><h2>Retrieval: 20 labelled queries, 22 chunks</h2><div id=\"ret\"><span class=\"meta\">Loading…</span></div><div class=\"meta\">BM25 is computed live in this Worker on every page load. Dense rows were measured offline on CPU with local models (evals/offline_embed.py).</div></div>\n<div class=\"card\"><h2>Faithfulness: 40 labelled answers</h2><div id=\"faith\"><span class=\"meta\">Loading…</span></div></div>\n<div class=\"card\"><h2>Score your own answer</h2><select id=\"c\"></select><div class=\"row\"><input id=\"a\" maxlength=\"500\" placeholder=\"Type an answer that cites the chunk above…\"><button id=\"go\">Score</button><button class=\"ghost\" id=\"gj\">Score + LLM judge</button></div><div id=\"out\" class=\"out meta\"></div></div>\n<footer>Runs on Cloudflare Workers · LLM judge uses free Workers AI and is rate limited · <a href=\"https://github.com/braylo777/agent-11-rag-eval-harness\">Source on GitHub</a></footer></div>\n<script>\nconst $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\"}[c]));\nconst cols=[\"precision@1\",\"precision@3\",\"recall@3\",\"recall@5\",\"mrr\"];\nconst row=(n,m)=>`<tr><td>${esc(n)}</td>${cols.map(c=>`<td>${m[c]}</td>`).join(\"\")}</tr>`;\nfetch(\"/api/eval\").then(r=>r.json()).then(j=>{let h=`<table><tr><th>Retriever</th>${cols.map(c=>`<th>${c}</th>`).join(\"\")}</tr>`+row(\"BM25 (live)\",j.live_bm25);\nfor(const [n,m] of Object.entries(j.offline?.models||{}))h+=row(n+\" (offline)\",m);$(\"ret\").innerHTML=h+\"</table>\";const f=j.citation_overlap;\n$(\"faith\").innerHTML=`<table><tr><th>Citation-overlap metric</th><th>Value</th></tr><tr><td>ROC AUC (faithful vs unfaithful)</td><td>${f.auc}</td></tr><tr><td>Accuracy at threshold ${f.threshold}</td><td>${f.accuracy}</td></tr><tr><td>Precision / recall (faithful class)</td><td>${f.precision} / ${f.recall}</td></tr><tr><td>Mean overlap: faithful / unfaithful</td><td>${f.mean_overlap_faithful} / ${f.mean_overlap_unfaithful}</td></tr><tr><td>LLM judge (Workers AI)</td><td>not yet run</td></tr></table>`});\nfetch(\"/api/data\").then(r=>r.json()).then(d=>{$(\"c\").innerHTML=d.chunks.map(c=>`<option value=\"${c.id}\">${c.id}: ${esc(c.text.slice(0,90))}</option>`).join(\"\")});\nasync function go(j){const a=$(\"a\").value.trim();if(!a)return;$(\"out\").textContent=\"Scoring…\";\nconst r=await fetch(\"/api/score\"+(j?\"?judge=1\":\"\"),{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify({answer:a,cites:[$(\"c\").value]})});const x=await r.json();\n$(\"out\").textContent=x.error?\"Error: \"+x.error:`Citation overlap: ${x.overlap}${x.overlap>=0.5?\" (faithful)\":\" (likely unfaithful)\"}`+(j?(\" · LLM judge: \"+(x.judge_error?\"unavailable (\"+x.judge_error+\")\":x.judge?\"SUPPORTED\":\"UNSUPPORTED\")):\"\")}\n$(\"go\").onclick=()=>go(0);$(\"gj\").onclick=()=>go(1);$(\"a\").onkeydown=e=>{if(e.key===\"Enter\")go(0)};\n</script></body></html>\n";

export default {
  async fetch(req, env) {
    const url = new URL(req.url), p = url.pathname;
    if (p === "/api/data") return json({ chunks: DATA.chunks, queries: DATA.queries.map(({ id, q, relevant }) => ({ id, q, relevant })) });
    if (p === "/api/eval") { const { rows, ...f } = scoreFaithfulness(); return json({ live_bm25: scoreRetrieval(bm25Rankings()), citation_overlap: f, offline: OFFLINE }); }
    if (req.method === "POST" && p === "/api/score") {
      const { answer, cites } = await body(req);
      if (!cap(answer) || !Array.isArray(cites) || cites.length > 5) return json({ error: "answer (<=500 chars) and cites (chunk ids) required" }, 400);
      const src = cites.map((id) => DATA.chunks.find((c) => c.id === id)?.text).filter(Boolean);
      if (!src.length) return json({ error: "unknown chunk ids" }, 400);
      const out = { overlap: r3(citationOverlap(answer, src)) };
      if (url.searchParams.get("judge") === "1") {
        if (await limited(req, env)) return json({ error: "Rate limit: try again in a minute." }, 429);
        try { out.judge = await judge(env, answer, src, ask); } catch (e) { out.judge_error = e.message; }
      }
      return json(out);
    }
    return new Response(page, { headers: { "content-type": "text/html;charset=utf-8" } });
  },
};
